/* NHPC Diploma in Operation Theatre Technology — syllabus mapped study module.
   Initial bilingual bank: 48 unique MCQs (24 practice + 24 mock); expand in reviewed batches.
   Based on NHPC Diploma in OTT Licensing Syllabus 2021. */
(()=>{const root=document.getElementById("ottContent");if(!root||root.dataset.ready==="1")return;root.dataset.ready="1";
const Q=[["Which anatomical plane divides the body into right and left parts?","शरीरलाई दायाँ र बायाँ भागमा छुट्याउने anatomical plane कुन हो?",["Coronal","Sagittal","Transverse","Oblique"],1,"The sagittal plane divides the body into right and left portions.","Sagittal plane ले शरीरलाई दायाँ र बायाँ भागमा विभाजन गर्छ।","Anatomy"],["Which organ is primarily responsible for gas exchange?","ग्यासको आदानप्रदान मुख्य रूपमा कुन अंगमा हुन्छ?",["Liver","Kidney","Lungs","Stomach"],2,"Gas exchange occurs across the alveolar-capillary membrane in the lungs.","फोक्सोका alveoli र capillaries बीच oxygen र carbon dioxide को आदानप्रदान हुन्छ।","Anatomy"],["What is the functional unit of the kidney?","मिर्गौलाको functional unit कुन हो?",["Neuron","Nephron","Alveolus","Hepatocyte"],1,"The nephron filters blood and forms urine.","Nephron ले रगत छानेर पिसाब बनाउन मद्दत गर्छ।","Anatomy"],["Which hormone lowers blood glucose?","रगतमा glucose घटाउने hormone कुन हो?",["Glucagon","Adrenaline","Insulin","Cortisol"],2,"Insulin promotes glucose uptake and storage, lowering blood glucose.","Insulin ले glucose को uptake र storage बढाएर blood glucose घटाउँछ।","Anatomy"],["The basic structural and functional unit of the nervous system is:","Nervous system को आधारभूत संरचनात्मक तथा कार्यात्मक एकाइ कुन हो?",["Neuron","Nephron","Osteon","Alveolus"],0,"A neuron receives and transmits nerve impulses.","Neuron ले nerve impulse ग्रहण र प्रसारण गर्छ।","Anatomy"],["Which electrolyte is the major extracellular cation?","कोषबाहिरको तरलमा मुख्य cation कुन हो?",["Potassium","Sodium","Magnesium","Phosphate"],1,"Sodium is the major extracellular cation and is important for fluid balance.","Sodium extracellular fluid को मुख्य cation हो र fluid balance मा महत्त्वपूर्ण छ।","Biochemistry"],["Which test is commonly used to assess renal filtration?","मिर्गौलाको filtration मूल्याङ्कन गर्न कुन परीक्षण प्रयोग गरिन्छ?",["Serum creatinine/eGFR","Serum amylase","Troponin only","Bilirubin only"],0,"Serum creatinine is used to estimate glomerular filtration rate (eGFR).","Serum creatinine बाट eGFR अनुमान गरी renal filtration मूल्याङ्कन गरिन्छ।","Biochemistry"],["The normal blood pH is approximately:","रगतको सामान्य pH लगभग कति हुन्छ?",["6.8–7.0","7.35–7.45","7.8–8.0","8.2–8.4"],1,"Normal arterial blood pH is maintained around 7.35–7.45.","सामान्य arterial blood pH 7.35–7.45 बीच कायम रहन्छ।","Biochemistry"],["Which route gives a drug directly into a vein?","औषधि सिधै नसामा दिने route कुन हो?",["Intramuscular","Subcutaneous","Intravenous","Intradermal"],2,"Intravenous administration delivers medication directly into the venous circulation.","Intravenous route बाट औषधि सिधै venous circulation मा पुग्छ।","Pharmacology"],["An antiseptic is primarily used on:","Antiseptic मुख्य रूपमा कहाँ प्रयोग गरिन्छ?",["Living tissue","Floors only","Metal instruments only","Waste bins"],0,"Antiseptics are chemical agents used on living tissue to reduce microorganisms.","Antiseptic जीवित tissue/छालामा microorganism घटाउन प्रयोग गरिन्छ।","Pharmacology"],["Which organism is commonly associated with surgical wound infection?","Surgical wound infection सँग सामान्यतया कुन जीवाणु सम्बन्धित हुन्छ?",["Staphylococcus aureus","Plasmodium vivax","Entamoeba histolytica","Rhinovirus"],0,"Staphylococcus aureus is a common cause of surgical site infection.","Staphylococcus aureus surgical site infection को सामान्य कारण हो।","Microbiology"],["What is the main purpose of hand hygiene before a sterile procedure?","Sterile procedure अघि hand hygiene गर्नुको मुख्य उद्देश्य के हो?",["Improve grip","Reduce transmission of microorganisms","Warm the hands","Remove glove powder only"],1,"Hand hygiene reduces microbial transmission and protects patients and staff.","Hand hygiene ले microorganism सर्ने जोखिम घटाएर बिरामी र स्वास्थ्यकर्मीलाई जोगाउँछ।","Microbiology"],["Which method is commonly used to sterilize heat-stable surgical instruments?","Heat-stable surgical instruments sterilize गर्न सामान्यतया कुन विधि प्रयोग गरिन्छ?",["Autoclaving","Wiping with water","Sun drying","Rinsing with saline"],0,"Validated steam sterilization in an autoclave is commonly used for heat- and moisture-stable instruments.","Heat र moisture सहने उपकरणमा validated autoclave steam sterilization प्रयोग गरिन्छ।","Microbiology"],["What does PPE stand for?","PPE को पूरा रूप के हो?",["Patient Protection Equipment","Personal Protective Equipment","Primary Prevention Element","Personal Procedure Evaluation"],1,"PPE means personal protective equipment, selected according to exposure risk.","PPE को अर्थ Personal Protective Equipment हो; exposure risk अनुसार छनोट गरिन्छ।","Microbiology"],["Who is a member of the sterile surgical team?","Sterile surgical team को सदस्य को हो?",["Scrub person","Receptionist","Ward clerk","Porter outside the room"],0,"The scrub person works within the sterile field and handles sterile instruments.","Scrub person sterile field भित्र काम गर्छ र sterile instruments सम्हाल्छ।","OT Technique"],["The main purpose of the circulating nurse/OT assistant is to:","Circulating nurse/OT assistant को मुख्य भूमिका के हो?",["Remain sterile at all times","Coordinate non-sterile activities and support the sterile team","Perform the operation independently","Prescribe antibiotics"],1,"The circulating team member coordinates room activities, documentation, supplies and patient safety outside the sterile field.","Circulating staff ले sterile field बाहिरका काम, documentation, सामान र patient safety समन्वय गर्छ।","OT Technique"],["A sterile field should be considered contaminated when:","कुन अवस्थामा sterile field दूषित भएको मानिन्छ?",["It is kept in view","A sterile item touches a non-sterile surface","A sterile drape is dry","The procedure is delayed briefly"],1,"Contact with a non-sterile surface compromises sterility and requires corrective action.","Non-sterile सतह छोएमा sterility बिग्रन्छ र आवश्यक corrective action लिनुपर्छ।","OT Technique"],["Which item is used to protect the patient and maintain a sterile operative field?","बिरामीलाई ढाकेर sterile operative field कायम गर्न कुन वस्तु प्रयोग हुन्छ?",["Surgical drape","Bed sheet from ward","Paper towel","Reusable blanket without processing"],0,"Sterile surgical drapes isolate the operative site and help maintain the sterile field.","Sterile surgical drape ले operation site छुट्याएर sterile field कायम गर्न मद्दत गर्छ।","OT Technique"],["What is the purpose of surgical hand antisepsis?","Surgical hand antisepsis को उद्देश्य के हो?",["Remove all skin cells","Reduce transient flora and suppress resident flora","Replace sterilization of instruments","Make gloves unnecessary"],1,"Surgical hand antisepsis reduces transient microorganisms and suppresses resident flora for the procedure.","यसले transient microorganism घटाउँछ र resident flora लाई दबाउँछ।","OT Technique"],["Which count is performed to prevent retained surgical items?","शल्यक्रियामा वस्तु शरीरभित्र छुट्न नदिन कुन count गरिन्छ?",["Sponge, sharp and instrument count","Patient meal count","Staff attendance count","Drug expiry count only"],0,"Counts of sponges, sharps and instruments are performed according to policy at defined stages.","Sponge, sharp र instrument count संस्थाको protocol अनुसार निश्चित चरणमा गरिन्छ।","OT Technique"],["What is the primary purpose of the WHO Surgical Safety Checklist?","WHO Surgical Safety Checklist को मुख्य उद्देश्य के हो?",["Increase operation speed only","Improve communication and reduce preventable harm","Replace consent","Avoid patient identification"],1,"The checklist supports team communication and checks key safety steps before, during and after surgery.","Checklist ले team communication र surgery का मुख्य safety steps जाँच्न मद्दत गर्छ।","OT Technique"],["Which gas is commonly used to insufflate the abdomen in laparoscopy?","Laparoscopy मा पेट फुलाउन सामान्यतया कुन gas प्रयोग गरिन्छ?",["Oxygen","Nitrogen","Carbon dioxide","Helium"],2,"Carbon dioxide is commonly used because it is non-flammable and readily absorbed.","Carbon dioxide non-flammable र शरीरले सजिलै absorb गर्ने भएकाले सामान्यतया प्रयोग हुन्छ।","OT Technique"],["A surgical specimen for histopathology should be:","Histopathology का लागि surgical specimen कसरी पठाउनुपर्छ?",["Left unlabelled","Correctly labelled and placed in the appropriate fixative as directed","Mixed with all other specimens","Discarded after removal"],1,"Correct identification, labelling and the laboratory-specified fixative preserve specimen integrity.","सही पहिचान, label र laboratory ले तोकेको fixative ले specimen सुरक्षित राख्छ।","OT Technique"],["Which device removes fluid and smoke from the operative field?","Operation field बाट fluid र smoke हटाउन कुन उपकरण प्रयोग हुन्छ?",["Suction system","Pulse oximeter","ECG electrode","Laryngoscope"],0,"Suction removes blood and fluids; dedicated smoke evacuation may be needed for surgical plume.","Suction ले रगत तथा fluid हटाउँछ; surgical plume का लागि छुट्टै smoke evacuation आवश्यक हुन सक्छ।","OT Technique"],["What is the safest immediate response to an electrical equipment fault during surgery?","Surgery चल्दा electrical equipment मा खराबी आएमा सुरक्षित तत्काल कदम के हो?",["Continue using it","Stop using it and alert the responsible team according to protocol","Touch exposed wires","Pour water on the device"],1,"Remove faulty equipment from use, maintain patient safety and report it according to local policy.","खराब उपकरण प्रयोग बन्द गरी बिरामी सुरक्षित राख्ने र protocol अनुसार जानकारी दिने।","OT Technique"],["Which monitoring device measures peripheral oxygen saturation?","Peripheral oxygen saturation मापन गर्ने उपकरण कुन हो?",["Pulse oximeter","Sphygmomanometer","Capnograph only","Thermometer"],0,"A pulse oximeter estimates oxygen saturation (SpO2) and pulse rate.","Pulse oximeter ले SpO2 र pulse rate अनुमान गर्छ।","Anaesthesia"],["Capnography primarily measures:","Capnography ले मुख्य रूपमा के मापन गर्छ?",["End-tidal carbon dioxide","Blood glucose","Haemoglobin","Urine output"],0,"Capnography monitors exhaled carbon dioxide, commonly displayed as end-tidal CO2 (EtCO2).","Capnography ले सास बाहिर निकाल्दा निस्कने CO2, सामान्यतया EtCO2, monitor गर्छ।","Anaesthesia"],["Which airway device is placed through the vocal cords into the trachea?","Vocal cords हुँदै trachea भित्र राखिने airway device कुन हो?",["Oropharyngeal airway","Endotracheal tube","Face mask","Nasal cannula"],1,"An endotracheal tube passes through the vocal cords into the trachea to secure the airway.","Endotracheal tube vocal cords पार गरी trachea मा राखेर airway सुरक्षित गर्छ।","Anaesthesia"],["The main purpose of pre-anaesthetic assessment is to:","Pre-anaesthetic assessment को मुख्य उद्देश्य के हो?",["Choose the patient's meal","Identify risks and plan safe anaesthesia","Guarantee no complications","Skip consent"],1,"Assessment identifies comorbidities, airway concerns, medications, allergies and risks to guide planning.","यसले रोग, airway, औषधि, allergy र जोखिम पहिचान गरी सुरक्षित योजना बनाउन मद्दत गर्छ।","Anaesthesia"],["Which drug class is commonly used for neuromuscular blockade?","Neuromuscular blockade का लागि कुन drug class प्रयोग हुन्छ?",["Neuromuscular blocking agents","Antacids","Antihistamines","Antifungals"],0,"Neuromuscular blocking agents produce temporary skeletal muscle paralysis and require appropriate airway and ventilation support.","यी औषधिले अस्थायी muscle paralysis गराउँछन्; airway र ventilation support आवश्यक हुन्छ।","Anaesthesia"],["Which position is commonly used for many abdominal operations?","धेरै abdominal operation मा सामान्यतया कुन position प्रयोग हुन्छ?",["Supine","Lithotomy in every case","Prone in every case","Sitting in every case"],0,"Supine is common for many abdominal procedures, but positioning must be tailored to the operation and patient.","धेरै abdominal surgery मा supine प्रयोग हुन्छ, तर procedure र बिरामीअनुसार position मिलाउनुपर्छ।","Patient Positioning"],["A major risk of prolonged lithotomy position is:","लामो समय lithotomy position राख्दा हुने प्रमुख जोखिम के हो?",["Peripheral nerve injury","Improved circulation in all patients","Reduced pressure injury risk","No risk"],0,"Prolonged or poorly supported lithotomy positioning can cause nerve compression and compartment-related injury.","लामो समय वा गलत support ले nerve compression र compartment सम्बन्धी चोट हुन सक्छ।","Patient Positioning"],["Which position is commonly used for posterior spinal surgery?","Posterior spinal surgery मा सामान्यतया कुन position प्रयोग हुन्छ?",["Prone","Supine","Lithotomy","Trendelenburg"],0,"Prone positioning provides access to the posterior spine; pressure points, eyes and airway require careful protection.","Prone position ले पछाडिको मेरुदण्डमा पहुँच दिन्छ; pressure points, आँखा र airway जोगाउनुपर्छ।","Patient Positioning"],["What is the first priority when receiving a patient in the operating room?","Operating room मा बिरामी प्राप्त गर्दा पहिलो प्राथमिकता के हो?",["Confirm identity using approved identifiers","Ask about payment","Start incision preparation immediately","Remove all jewellery without explanation"],0,"Correct patient identification and matching the procedure and consent are essential safety checks.","सही बिरामी, procedure र consent मिलाउनु आधारभूत safety check हो।","Preoperative Care"],["Which document confirms that the patient has been informed and agrees to the procedure?","बिरामीलाई जानकारी दिइएको र procedure गर्न सहमति भएको पुष्टि गर्ने कागजात कुन हो?",["Informed consent","Discharge summary","Instrument list","Diet chart"],0,"Informed consent documents a voluntary decision after adequate explanation by the responsible clinician.","जिम्मेवार clinician ले पर्याप्त जानकारी दिएपछि बिरामीले स्वेच्छाले दिएको सहमति document गरिन्छ।","Preoperative Care"],["Which action helps prevent wrong-site surgery?","गलत स्थानमा surgery हुन नदिन कुन कदमले मद्दत गर्छ?",["Site marking and team verification","Relying on memory","Skipping the time-out","Preparing two patients together"],0,"Site marking, identity/procedure verification and a team time-out reduce wrong-site risk.","Site marking, बिरामी/प्रक्रिया verification र team time-out ले गलत site को जोखिम घटाउँछ।","Preoperative Care"],["What is the purpose of surgical skin preparation?","Surgical skin preparation को उद्देश्य के हो?",["Reduce microorganisms at the operative site","Sterilize deep organs","Replace hand hygiene","Remove the need for antibiotics in all cases"],0,"Appropriate antiseptic skin preparation reduces microbial load at the incision site.","उपयुक्त antiseptic ले incision site मा microorganism को मात्रा घटाउँछ।","Surgery"],["Which phase of wound healing is characterized by collagen deposition and granulation tissue formation?","Collagen जम्ने र granulation tissue बन्ने wound healing चरण कुन हो?",["Proliferative phase","Haemostasis only","Maturation only","Immediate contamination"],0,"The proliferative phase includes fibroblast activity, collagen deposition, angiogenesis and granulation tissue formation.","Proliferative phase मा fibroblast, collagen, नयाँ रक्तनली र granulation tissue बन्छ।","Surgery"],["Which instrument is commonly used to grasp tissue atraumatically?","Tissue लाई कम चोट पुर्‍याएर समात्न कुन instrument प्रयोग हुन्छ?",["Appropriate atraumatic forceps","Bone saw","Suction catheter","Retractor only"],0,"Atraumatic forceps are selected to hold delicate tissue while minimizing crush injury.","Delicate tissue कम चोट पुर्‍याएर समात्न atraumatic forceps छानिन्छ।","Surgical Instruments"],["Which suture is generally absorbed by the body over time?","शरीरले समयसँगै absorb गर्ने suture कुन हो?",["Absorbable suture","Permanent non-absorbable suture","Stainless steel wire only","Silk in every case"],0,"Absorbable sutures degrade through hydrolysis or enzymatic processes; selection depends on tissue and procedure.","Absorbable suture hydrolysis वा enzymatic प्रक्रियाबाट घट्छ; छनोट tissue र procedure अनुसार हुन्छ।","Surgical Materials"],["What is the purpose of a surgical drain?","Surgical drain को उद्देश्य के हो?",["Allow collection or removal of fluid/air from a surgical site","Sterilize the wound","Replace haemostasis","Measure blood glucose"],0,"Drains may remove or monitor fluid or air when clinically indicated; they are not required in every operation.","आवश्यक अवस्थामा drain ले surgical site बाट fluid वा air निकाल्न/monitor गर्न मद्दत गर्छ।","Surgery"],["Which procedure uses an endoscope to visualize the abdominal cavity through small ports?","सानो port बाट endoscope प्रयोग गरी पेटभित्र हेर्ने procedure कुन हो?",["Laparoscopy","Thoracotomy","Craniotomy","Arthrodesis"],0,"Laparoscopy uses a camera and instruments introduced through small abdominal ports.","Laparoscopy मा पेटका साना port बाट camera र instruments प्रवेश गराइन्छ।","Operative Procedures"],["Which operation removes the gallbladder?","Gallbladder हटाउने operation कुन हो?",["Cholecystectomy","Appendectomy","Nephrectomy","Colectomy"],0,"Cholecystectomy is surgical removal of the gallbladder.","Cholecystectomy भनेको gallbladder हटाउने शल्यक्रिया हो।","Operative Procedures"],["Which operation removes the appendix?","Appendix हटाउने operation कुन हो?",["Appendectomy","Gastrectomy","Hysterectomy","Mastectomy"],0,"Appendectomy is removal of the appendix, commonly for appendicitis.","Appendectomy मा appendix हटाइन्छ, प्रायः appendicitis का लागि।","Operative Procedures"],["Which specialty commonly performs cataract extraction?","Cataract extraction कुन specialty अन्तर्गत पर्छ?",["Ophthalmology","Urology","Orthopaedics","Neurosurgery"],0,"Cataract surgery is an ophthalmic procedure involving removal of the cloudy lens and usually intraocular lens implantation.","Cataract surgery आँखाको lens हटाएर प्रायः intraocular lens राख्ने ophthalmic procedure हो।","Operative Procedures"],["Which procedure is used to repair a hernia?","Hernia मर्मत गर्ने procedure कुन हो?",["Herniorrhaphy/hernia repair","Cholecystectomy","Cystoscopy","Myringotomy"],0,"Hernia repair returns or reinforces tissue at the defect, with technique selected by the surgeon.","Hernia repair मा defect भएको भाग मर्मत वा reinforce गरिन्छ।","Operative Procedures"],["What is the key purpose of haemostasis during surgery?","Surgery गर्दा haemostasis को मुख्य उद्देश्य के हो?",["Control bleeding","Increase blood loss","Delay wound healing","Sterilize instruments"],0,"Haemostasis controls bleeding and supports safe visualization and patient stability.","Haemostasis ले रक्तस्राव नियन्त्रण गरी सुरक्षित operation र बिरामीको स्थिरता कायम गर्न मद्दत गर्छ।","Surgery"],["Which complication may occur after surgery due to reduced ventilation and immobility?","शल्यक्रियापछि ventilation कम र चलायमानता घट्दा कुन complication हुन सक्छ?",["Atelectasis","Improved lung expansion","Hyperthyroidism","Cataract"],0,"Atelectasis is collapse of alveoli and can occur after surgery, especially with shallow breathing and immobility.","Atelectasis भनेको alveoli खुम्चिनु हो; shallow breathing र immobility पछि हुन सक्छ।","Postoperative Care"],["A patient develops sudden severe bleeding during surgery. The OT team should first:","Surgery चल्दा अचानक धेरै रक्तस्राव भएमा OT team ले पहिले के गर्नुपर्छ?",["Alert the surgeon/anesthesia team and follow emergency haemorrhage protocol","Leave the room","Continue routine cleaning","Remove monitoring"],0,"Immediate team communication, support of circulation and the local haemorrhage protocol are essential.","तुरुन्त team लाई जानकारी, circulation support र संस्थाको haemorrhage protocol पालना आवश्यक हुन्छ।","Emergency Care"],["Which statement best describes balanced anaesthesia?","Balanced anaesthesia भन्नाले के बुझिन्छ?",["Use of several agents/techniques to achieve desired components of anaesthesia","Use of only one drug in every patient","Keeping the patient awake throughout surgery","Avoiding monitoring"],0,"Balanced anaesthesia combines suitable agents or techniques to provide hypnosis, analgesia and immobility while limiting adverse effects.","Balanced anaesthesia मा उपयुक्त औषधि/विधि मिलाएर hypnosis, analgesia र immobility प्राप्त गरिन्छ र side effect कम गर्ने प्रयास गरिन्छ।","Anaesthesia"],["Which is a common purpose of premedication before anaesthesia?","Anaesthesia अघि premedication दिनुको सामान्य उद्देश्य के हो?",["Reduce anxiety and provide selected effects such as analgesia or secretion reduction","Replace airway assessment","Guarantee absence of aspiration","Replace informed consent"],0,"Premedication is selected for the individual patient and may reduce anxiety, pain or secretions as clinically indicated.","बिरामीको अवस्था अनुसार premedication ले anxiety, pain वा secretion घटाउन मद्दत गर्न सक्छ।","Anaesthesia"],["Spinal anaesthesia is administered into the:","Spinal anaesthesia कहाँ दिइन्छ?",["Subarachnoid space containing CSF","Pleural cavity","Peritoneal cavity","Epidural space only"],0,"Spinal anaesthesia is injected into the subarachnoid space, where it mixes with cerebrospinal fluid.","Spinal anaesthesia subarachnoid space मा CSF सँग मिसिने गरी दिइन्छ।","Anaesthesia"],["Epidural anaesthesia is administered into the:","Epidural anaesthesia कहाँ दिइन्छ?",["Epidural space outside the dura","Subarachnoid space","Ventricular system","Pleural space"],0,"An epidural injection is placed in the epidural space outside the dura mater.","Epidural injection dura mater बाहिरको epidural space मा दिइन्छ।","Anaesthesia"],["Which local anaesthetic toxicity sign may occur early in the central nervous system?","Local anaesthetic systemic toxicity मा CNS को प्रारम्भिक संकेत कुन हुन सक्छ?",["Circumoral numbness, tinnitus or metallic taste","Hair loss","Jaundice","Polyuria"],0,"Early neurological symptoms can include circumoral numbness, tinnitus, metallic taste, agitation or seizures; urgent protocol-based care is required.","मुख वरिपरि numbness, कानमा आवाज, metallic taste, बेचैनी वा seizure देखिन सक्छ; तुरुन्त protocol अनुसार उपचार चाहिन्छ।","Anaesthesia"],["Which monitor is essential for continuous assessment of oxygenation during general anaesthesia?","General anaesthesia मा oxygenation निरन्तर हेर्न कुन monitor महत्त्वपूर्ण हुन्छ?",["Pulse oximeter","Urine dipstick","Glucometer only","Peak flow meter only"],0,"Pulse oximetry provides continuous SpO2 monitoring and should be interpreted with the full clinical picture.","Pulse oximeter ले SpO2 निरन्तर देखाउँछ; अन्य clinical जानकारीसँग मिलाएर बुझ्नुपर्छ।","Anaesthesia"],["A sudden rise in end-tidal CO2 with rigidity and hyperthermia during anaesthesia may suggest:","Anaesthesia का बेला EtCO2 अचानक बढ्नु, शरीर कडा हुनु र ज्वरो आउनु कुन अवस्थाको संकेत हुन सक्छ?",["Malignant hyperthermia","Hypoglycaemia only","Simple motion sickness","Cataract"],0,"Malignant hyperthermia is a life-threatening anaesthetic emergency; activate the emergency protocol and use specific treatment such as dantrolene per protocol.","Malignant hyperthermia जीवन जोखिमपूर्ण emergency हो; तुरुन्त emergency protocol र dantrolene सहितको उपचार आवश्यक पर्न सक्छ।","Anaesthesia Complications"],["Which drug is a commonly used neuromuscular blocking agent?","Neuromuscular blocking agent को उदाहरण कुन हो?",["Rocuronium","Paracetamol","Amoxicillin","Omeprazole"],0,"Rocuronium is a non-depolarizing neuromuscular blocker used by trained anaesthesia professionals with airway and ventilation support.","Rocuronium non-depolarizing muscle relaxant हो; airway र ventilation support सहित प्रशिक्षित टोलीले प्रयोग गर्छ।","Anaesthesia Drugs"],["Which drug is a reversal agent for benzodiazepine sedation in selected situations?","केही अवस्थामा benzodiazepine को प्रभाव उल्ट्याउन कुन औषधि प्रयोग हुन्छ?",["Flumazenil","Naloxone","Atropine","Adrenaline"],0,"Flumazenil antagonizes benzodiazepines; use requires careful assessment because resedation and seizures may occur in some patients.","Flumazenil ले benzodiazepine को प्रभाव रोक्छ; केही बिरामीमा पुनः sedation वा seizure जोखिम भएकाले सावधानी चाहिन्छ।","Anaesthesia Drugs"],["Which medicine reverses opioid-induced respiratory depression?","Opioid का कारण भएको respiratory depression उल्ट्याउन कुन औषधि प्रयोग हुन्छ?",["Naloxone","Flumazenil","Neostigmine","Lidocaine"],0,"Naloxone is an opioid antagonist used to reverse opioid toxicity, with repeat dosing and monitoring sometimes required.","Naloxone opioid antagonist हो; आवश्यक परे दोहोर्‍याएर दिन र बिरामी monitor गर्नुपर्छ।","Anaesthesia Drugs"],["Which drug class is used to treat bronchospasm?","Bronchospasm उपचार गर्न कुन drug class प्रयोग हुन्छ?",["Bronchodilators","Anticoagulants","Antifungals","Antacids"],0,"Bronchodilators such as inhaled beta-2 agonists can relieve bronchospasm according to clinical protocol.","Inhaled beta-2 agonist जस्ता bronchodilator ले protocol अनुसार bronchospasm घटाउन सक्छ।","Anaesthesia Drugs"],["Which drug class may be used to increase vascular tone in severe hypotension?","गम्भीर hypotension मा vascular tone बढाउन कुन औषधि वर्ग प्रयोग हुन सक्छ?",["Vasopressors","Antacids","Antihistamines","Antifungals"],0,"Vasopressors support blood pressure in selected shock states and require close monitoring.","केही shock अवस्थामा vasopressor ले blood pressure support गर्छ; नजिकबाट monitor गर्नुपर्छ।","Anaesthesia Drugs"],["Which rhythm is shockable during adult cardiac arrest?","वयस्क cardiac arrest मा कुन rhythm shockable हुन्छ?",["Ventricular fibrillation","Asystole","Pulseless electrical activity","Normal sinus rhythm"],0,"Ventricular fibrillation and pulseless ventricular tachycardia are shockable rhythms; asystole and PEA are not.","Ventricular fibrillation र pulseless VT shockable rhythm हुन्; asystole र PEA shockable होइनन्।","CPR"],["For an adult with cardiac arrest, what is the recommended chest compression rate?","वयस्क cardiac arrest मा chest compression को सिफारिस गरिएको गति कति हो?",["100–120 per minute","40–60 per minute","60–80 per minute","More than 160 per minute"],0,"Adult CPR uses a compression rate of 100–120 per minute with adequate depth and full recoil.","Adult CPR मा प्रति मिनेट 100–120 compression, पर्याप्त गहिराइ र पूर्ण recoil आवश्यक हुन्छ।","CPR"],["What is the recommended adult chest compression depth?","वयस्कमा chest compression को सिफारिस गरिएको गहिराइ कति हो?",["At least 5 cm but not more than 6 cm","1 cm","2 cm","8–10 cm"],0,"For most adults, compress at least 5 cm while avoiding excessive depth beyond 6 cm.","वयस्कमा कम्तीमा 5 cm तर 6 cm भन्दा बढी नहुने गरी compression गरिन्छ।","CPR"],["When an AED arrives during cardiac arrest, the team should:","Cardiac arrest हुँदा AED आइपुगेपछि के गर्नुपर्छ?",["Apply it promptly and follow its voice prompts while minimizing interruptions","Wait until CPR has stopped for several minutes","Ignore it if a manual pulse is not felt","Use it only after transport"],0,"Attach the AED as soon as available, follow prompts and resume compressions immediately after shock/no-shock advice.","AED छिटो जोडेर निर्देशन पालना गर्ने र shock/no-shock पछि तुरुन्त compression सुरु गर्ने।","CPR"],["Which IV fluid is an example of an isotonic crystalloid?","Isotonic crystalloid को उदाहरण कुन हो?",["0.9% sodium chloride","10% dextrose","3% sodium chloride","Albumin"],0,"0.9% sodium chloride is an isotonic crystalloid commonly used when clinically indicated.","0.9% sodium chloride isotonic crystalloid हो र आवश्यक clinical अवस्थामा प्रयोग गरिन्छ।","Fluids"],["Which is an example of a colloid solution?","Colloid solution को उदाहरण कुन हो?",["Albumin","0.9% saline","Ringer's lactate","5% dextrose in water"],0,"Albumin is a colloid; fluid choice depends on indication, risks and current guidance.","Albumin colloid हो; fluid छनोट indication, जोखिम र guideline अनुसार हुन्छ।","Fluids"],["Which blood group is the universal red-cell donor in emergency uncrossmatched transfusion?","Emergency मा crossmatch नभएको अवस्थामा red-cell transfusion का लागि universal donor कुन हो?",["O negative","AB positive","A positive","B negative"],0,"O-negative red cells are commonly used for emergency uncrossmatched transfusion when indicated, following transfusion policy.","आवश्यक emergency अवस्थामा policy अनुसार O-negative red cells प्रयोग गरिन्छ।","Blood Transfusion"],["Which test is performed before a planned blood transfusion to assess compatibility?","नियोजित blood transfusion अघि compatibility जाँच्न कुन परीक्षण गरिन्छ?",["Crossmatch","Urine culture","Liver biopsy","Skin prick test"],0,"Crossmatching checks compatibility between donor red cells and recipient plasma before transfusion.","Crossmatch ले donor red cells र recipient plasma बीच compatibility जाँच्छ।","Blood Transfusion"],["Fever, chills, back pain or hypotension during transfusion may indicate:","Transfusion चल्दा ज्वरो, काँप्ने, ढाड दुख्ने वा hypotension भएमा के शंका गर्नुपर्छ?",["Transfusion reaction","Normal expected response","Improved oxygenation","Simple hunger"],0,"Stop the transfusion immediately, maintain IV access with appropriate fluid per protocol, assess the patient and notify the responsible clinician/blood bank.","Transfusion तुरुन्त रोक्ने, protocol अनुसार IV access कायम गर्ने, बिरामी जाँच्ने र जिम्मेवार clinician/blood bank लाई खबर गर्ने।","Blood Transfusion"],["Which blood component is primarily used to improve oxygen-carrying capacity?","Oxygen बोक्ने क्षमता बढाउन मुख्य रूपमा कुन blood component दिइन्छ?",["Packed red blood cells","Platelet concentrate","Fresh frozen plasma","Cryoprecipitate"],0,"Packed red blood cells increase haemoglobin and oxygen-carrying capacity when transfusion is indicated.","आवश्यक अवस्थामा packed red cells ले haemoglobin र oxygen बोक्ने क्षमता बढाउँछ।","Blood Transfusion"],["Which action is essential before administering any medication?","कुनै औषधि दिनुअघि कुन कार्य अनिवार्य छ?",["Verify patient, medicine, dose, route, time, allergy and order","Assume the label is correct","Use another patient's chart","Skip documentation"],0,"Medication safety includes patient identification, correct drug/dose/route/time, allergy checks and documentation.","औषधि सुरक्षा लागि बिरामी, औषधि, मात्रा, route, समय, allergy र documentation जाँचिन्छ।","Patient Safety"],["What is the primary purpose of informed consent?","Informed consent को मुख्य उद्देश्य के हो?",["Support an informed, voluntary decision by the patient","Transfer all clinical responsibility to the patient","Replace explanation","Permit procedures without identification"],0,"Consent follows adequate information about the procedure, material risks, benefits and alternatives, and must be voluntary.","Procedure, जोखिम, फाइदा र विकल्पबारे जानकारी पाएपछि बिरामीले स्वेच्छाले निर्णय गर्नु consent हो।","Medico-legal"],["Which record is important for legal accountability in the operating room?","OT मा कानुनी जवाफदेहिताका लागि कुन अभिलेख महत्त्वपूर्ण हुन्छ?",["Accurate contemporaneous patient and procedure documentation","Undated personal notes only","Verbal memory alone","Blank checklist"],0,"Clear, timely and accurate records support continuity, safety and accountability.","स्पष्ट, समयमै र सही documentation ले continuity, safety र accountability कायम गर्छ।","Medico-legal"],["Which position is commonly used for pelvic and perineal procedures?","Pelvic र perineal procedure मा सामान्यतया कुन position प्रयोग हुन्छ?",["Lithotomy","Prone","Sitting","Jackknife for every procedure"],0,"Lithotomy provides access to the perineum; protect pressure points and avoid excessive hip flexion/abduction.","Lithotomy ले perineum मा पहुँच दिन्छ; pressure points जोगाउने र hip अत्यधिक मोड्न/फैलाउन हुँदैन।","Positioning"],["Which complication is associated with prolonged pressure over the common peroneal nerve in lithotomy?","Lithotomy मा common peroneal nerve मा लामो दबाब परेमा कुन complication हुन सक्छ?",["Foot drop","Cataract","Hearing loss","Jaundice"],0,"Common peroneal nerve compression can cause weakness of ankle dorsiflexion and foot drop.","Common peroneal nerve थिचिँदा खुट्टाको dorsiflexion कमजोर भएर foot drop हुन सक्छ।","Positioning"],["Which position may be used for some thyroid and anterior neck operations?","केही thyroid र अगाडिको घाँटीको operation मा कुन position प्रयोग हुन सक्छ?",["Supine with neck appropriately extended","Prone with neck flexed","Lithotomy","Trendelenburg in all cases"],0,"Supine with carefully supported neck extension may improve access; avoid excessive extension and protect the airway.","Supine मा घाँटीलाई सावधानीपूर्वक extend गर्दा पहुँच सजिलो हुन्छ; अत्यधिक extension नगर्नुहोस्।","Positioning"],["Why is an electrosurgical return electrode used in monopolar electrosurgery?","Monopolar electrosurgery मा return electrode किन प्रयोग गरिन्छ?",["To complete the electrical circuit and disperse current safely","To sterilize the instrument","To measure blood pressure","To provide oxygen"],0,"The return electrode completes the circuit and spreads current over a large area to reduce thermal injury risk.","Return electrode ले circuit पूरा गर्छ र current ठूलो क्षेत्रमा फैलाएर burn जोखिम घटाउँछ।","OT Equipment"],["What is a key safety precaution when using electrosurgery?","Electrosurgery प्रयोग गर्दा मुख्य safety precaution के हो?",["Keep alcohol-based prep fully dry and manage oxygen/fire risk","Use it beside pooled alcohol prep","Ignore the return electrode","Place drapes over active electrode tips"],0,"Allow alcohol-based skin preparation to dry fully, prevent pooling and coordinate oxygen delivery to reduce surgical fire risk.","Alcohol-based skin prep पूर्ण सुक्न दिनु, जम्मा हुन नदिनु र oxygen व्यवस्थापन गर्नु surgical fire जोखिम घटाउने उपाय हुन्।","OT Equipment"],["Which instrument is used to view the urinary bladder endoscopically?","Urinary bladder भित्र endoscope बाट हेर्न कुन instrument प्रयोग हुन्छ?",["Cystoscope","Bronchoscope","Gastroscope","Arthroscope"],0,"Cystoscopy uses a cystoscope to examine the urethra and bladder and may allow selected procedures.","Cystoscope ले urethra र bladder हेर्न तथा केही procedure गर्न मद्दत गर्छ।","Urology"],["Which procedure removes the uterus?","Uterus हटाउने operation कुन हो?",["Hysterectomy","Oophorectomy","Cystectomy","Colectomy"],0,"Hysterectomy is surgical removal of the uterus; the approach depends on clinical indication.","Hysterectomy मा uterus हटाइन्छ; विधि clinical indication अनुसार छानिन्छ।","Gynaecology"],["Which procedure repairs a torn ligament?","च्यातिएको ligament मर्मत गर्ने procedure कुन हो?",["Ligament repair/reconstruction","Gastrectomy","Cataract extraction","Nephrostomy"],0,"Ligament repair or reconstruction restores stability depending on the injury and joint.","Ligament repair/reconstruction ले चोट र joint अनुसार स्थिरता पुनःस्थापित गर्छ।","Orthopaedics"],["Which instrument is commonly used to inspect the bronchial tree?","Bronchial tree निरीक्षण गर्न कुन instrument प्रयोग हुन्छ?",["Bronchoscope","Cystoscope","Colonoscope","Otoscope"],0,"Bronchoscopy allows visualization of the trachea and bronchi and may be diagnostic or therapeutic.","Bronchoscopy बाट trachea र bronchi हेर्न तथा आवश्यक procedure गर्न सकिन्छ।","Thoracic/ENT"],["Which operation creates an opening in the trachea?","Trachea मा opening बनाउने operation कुन हो?",["Tracheostomy","Thoracotomy","Laparotomy","Craniotomy"],0,"Tracheostomy creates an opening into the trachea to establish an airway when indicated.","Tracheostomy मा आवश्यक अवस्थामा airway बनाउन trachea मा opening बनाइन्छ।","ENT"],["Which procedure is used to remove a kidney?","मिर्गौला हटाउने operation कुन हो?",["Nephrectomy","Cystoscopy","Herniorrhaphy","Colectomy"],0,"Nephrectomy is surgical removal of all or part of a kidney, depending on the procedure.","Nephrectomy मा procedure अनुसार मिर्गौलाको केही वा सबै भाग हटाइन्छ।","Urology"],["Which procedure is commonly used to remove a breast?","स्तन हटाउने operation कुन हो?",["Mastectomy","Myringotomy","Splenectomy","Thyroidectomy"],0,"Mastectomy is surgical removal of breast tissue; the extent depends on the indication.","Mastectomy मा indication अनुसार breast tissue हटाइन्छ।","General Surgery"],["Which procedure creates an opening into the abdomen to access abdominal organs?","पेटका अंगमा पहुँचका लागि abdomen खोल्ने incision/procedure कुन हो?",["Laparotomy","Thoracotomy","Craniotomy","Arthroscopy"],0,"Laparotomy is an abdominal incision to access the peritoneal cavity and abdominal organs.","Laparotomy भनेको पेट खोलेर peritoneal cavity र abdominal organs मा पहुँच बनाउनु हो।","General Surgery"],["Which surgical procedure is used to remove the spleen?","Spleen हटाउने operation कुन हो?",["Splenectomy","Pancreatectomy","Appendectomy","Thyroidectomy"],0,"Splenectomy is surgical removal of the spleen; infection prevention and vaccination planning are important after total splenectomy.","Splenectomy मा spleen हटाइन्छ; total splenectomy पछि संक्रमण रोकथाम र vaccination योजना महत्त्वपूर्ण हुन्छ।","General Surgery"],["Which procedure is used to replace a diseased heart valve?","बिरामी भएको heart valve बदल्ने procedure कुन हो?",["Heart valve replacement","Appendectomy","Cystoscopy","Myringotomy"],0,"Valve replacement substitutes a diseased valve with a prosthetic valve when indicated.","आवश्यक अवस्थामा खराब valve लाई prosthetic valve ले बदलिन्छ।","Cardiac Surgery"],["What does CABG stand for?","CABG को पूरा रूप के हो?",["Coronary artery bypass grafting","Central airway balloon guidance","Cardiac atrial blood grouping","Coronary angiographic biopsy"],0,"CABG creates a bypass route around narrowed coronary arteries to improve myocardial blood supply.","CABG ले साँघुरिएको coronary artery वरिपरि bypass बाटो बनाएर मुटुको मांसपेशीमा रगत पुर्‍याउँछ।","Cardiac Surgery"],["Which instrument is used to view the inside of a joint?","Joint भित्र हेर्न कुन instrument प्रयोग हुन्छ?",["Arthroscope","Bronchoscope","Cystoscope","Otoscope"],0,"Arthroscopy uses a small camera to visualize a joint and perform selected minimally invasive procedures.","Arthroscope सानो camera हो जसबाट joint भित्र हेरेर केही minimally invasive procedure गरिन्छ।","Orthopaedics"],["Which complication is characterized by widespread activation of coagulation with consumption of platelets and clotting factors?","Platelet र clotting factor खपत हुँदै व्यापक coagulation सक्रिय हुने complication कुन हो?",["Disseminated intravascular coagulation (DIC)","Simple bruising only","Atelectasis","Hypothermia"],0,"DIC is a serious acquired syndrome involving systemic coagulation activation, microthrombi and bleeding due to factor consumption.","DIC मा शरीरभर coagulation सक्रिय भई microthrombi बन्ने र factor खपतका कारण bleeding हुन सक्छ।","Complications"],["Which postoperative finding may indicate wound dehiscence?","Postoperative wound dehiscence को संकेत कुन हुन सक्छ?",["Separation of wound edges","Normal scar maturation","Mild expected bruising only","Hair growth"],0,"Wound dehiscence is partial or complete separation of previously closed wound edges and requires urgent clinical assessment.","बन्द गरिएको घाउका किनारा आंशिक वा पूर्ण छुट्टिनु wound dehiscence हो; तुरुन्त clinical assessment चाहिन्छ।","Complications"],["A patient becomes suddenly breathless after surgery with chest pain and low oxygen saturation. Which serious complication should be considered?","Surgery पछि अचानक सास फेर्न गाह्रो, छाती दुख्ने र oxygen कम भएमा कुन गम्भीर complication सोच्नुपर्छ?",["Pulmonary embolism","Simple wound itch","Cataract","Otitis externa"],0,"Pulmonary embolism is a potentially life-threatening cause of acute postoperative dyspnoea and requires urgent evaluation.","Pulmonary embolism postoperative acute dyspnoea को जीवन जोखिमपूर्ण कारण हुन सक्छ; तुरुन्त जाँच चाहिन्छ।","Complications"],["Which practice helps prevent retained surgical items?","Surgery पछि वस्तु शरीरभित्र छुट्न नदिन कुन अभ्यास उपयोगी हुन्छ?",["Standardized counts, reconciliation and documented handover","Estimate by memory","Count only after skin closure","Discard count records"],0,"Standardized counts at required stages, discrepancy escalation and documentation reduce retained-item risk.","निर्धारित चरणमा count, फरक परे escalation र documentation ले retained item जोखिम घटाउँछ।","Patient Safety"],["What is the purpose of an ultrasonic bath for instruments?","Instrument सफा गर्दा ultrasonic bath को उद्देश्य के हो?",["Dislodge soil from hard-to-reach surfaces by cavitation","Sterilize every instrument automatically","Replace inspection and packaging","Sharpen cutting edges"],0,"Ultrasonic cleaning uses cavitation to help remove debris from joints and crevices; it does not replace rinsing, inspection and sterilization.","Ultrasonic cavitation ले joint/crevice बाट मैलो हटाउन मद्दत गर्छ; यसले rinsing, inspection र sterilization प्रतिस्थापन गर्दैन।","Practical Skills"],["What should be done with a visibly dirty reusable instrument before sterilization?","दृश्य रूपमा फोहोर reusable instrument sterilization अघि के गर्नुपर्छ?",["Clean it thoroughly according to validated instructions","Wrap it without cleaning","Wipe only the handle","Put it directly into storage"],0,"Cleaning removes organic/inorganic soil that can interfere with disinfection or sterilization; follow validated device instructions.","Cleaning ले मैलो हटाउँछ, जसले disinfection/sterilization मा बाधा पुर्‍याउन सक्छ; validated निर्देश पालना गर्नुपर्छ।","Practical Skills"],["Which method is appropriate for sterilizing a heat-sensitive flexible endoscope?","Heat-sensitive flexible endoscope sterilize गर्न कुन विधि उपयुक्त हुन्छ?",["A validated low-temperature process compatible with the device","Routine dry heat at very high temperature","Boiling for one minute","Wiping with plain water"],0,"Use a validated high-level disinfection or sterilization process as required by device classification and manufacturer instructions; many flexible endoscopes are heat-sensitive.","Device classification र manufacturer निर्देशअनुसार validated high-level disinfection वा sterilization प्रयोग गर्नुपर्छ; धेरै flexible endoscope heat-sensitive हुन्छन्।","Practical Skills"],["Which waste category should a blood-soaked dressing generally enter under a colour-coded healthcare waste system?","रगतले भिजेको dressing लाई सामान्यतया कुन waste category मा राखिन्छ?",["Infectious/soiled clinical waste according to local colour code","General recyclable paper","Food waste","Uncontaminated glass"],0,"Segregate blood-contaminated dressings as infectious waste using the applicable national and facility colour code.","रगत लागेको dressing लाई राष्ट्रिय तथा संस्थागत colour code अनुसार infectious waste मा छुट्याउनुपर्छ।","Practical Skills"],["Which check is important before using an anaesthesia breathing circuit?","Anaesthesia breathing circuit प्रयोग गर्नुअघि कुन जाँच महत्त्वपूर्ण हुन्छ?",["Leak and function check according to machine checklist","Check only the colour","Assume it is safe if recently stored","Disconnect the oxygen supply"],0,"A pre-use machine and breathing-system check identifies leaks, disconnections and malfunction before patient connection.","Pre-use machine र breathing system check ले बिरामी जोड्नुअघि leak, disconnection र खराबी पत्ता लगाउँछ।","Practical Skills"],["Which device is used to deliver a controlled concentration of oxygen to a patient?","बिरामीलाई नियन्त्रित oxygen concentration दिन कुन उपकरण प्रयोग गरिन्छ?",["Oxygen delivery system with an appropriate interface","Surgical retractor","Suction jar","Electrosurgical pencil"],0,"Oxygen delivery devices are selected based on the required flow, concentration and patient condition.","आवश्यक flow, concentration र बिरामीको अवस्थाअनुसार oxygen delivery device छानिन्छ।","Anaesthesia Equipment"],["Which instrument is commonly used to retract soft tissue during an operation?","Operation गर्दा soft tissue तानिराख्न कुन instrument प्रयोग हुन्छ?",["Surgical retractor","Suture needle","Artery forceps only","Bone drill"],0,"Retractors hold tissues aside to improve exposure; the type and pressure should suit the tissue.","Retractor ले tissue हटाएर operation site देखाउँछ; tissue अनुसार सही प्रकार र दबाब प्रयोग गर्नुपर्छ।","Surgical Instruments"],["Which instrument is commonly used to clamp a blood vessel temporarily?","रक्तनली अस्थायी रूपमा बन्द गर्न कुन instrument प्रयोग हुन्छ?",["Artery forceps/hemostat","Mayo scissors","Needle holder","Suction tip"],0,"A hemostat can clamp a vessel or tissue temporarily to assist haemostasis.","Hemostat ले रक्तनली वा tissue अस्थायी रूपमा समातेर haemostasis मा सहयोग गर्छ।","Surgical Instruments"],["Which instrument is designed to hold a suture needle?","Suture needle समात्न कुन instrument बनाइएको हो?",["Needle holder","Towel clip","Sponge forceps","Bone curette"],0,"A needle holder securely grips the surgical needle during suturing.","Needle holder ले suturing गर्दा surgical needle सुरक्षित रूपमा समात्छ।","Surgical Instruments"],["Which action is appropriate when a surgical count discrepancy occurs?","Surgical count नमिलेमा उपयुक्त कदम के हो?",["Immediately inform the team, repeat/reconcile the count and follow policy before closure","Ignore the discrepancy","Document a correct count without checking","Dispose of all used sponges"],0,"A discrepancy must be communicated and investigated promptly, with systematic search and escalation under facility policy.","Count नमिलेमा तुरुन्त जानकारी दिई फेरि जाँच/मिलान गर्ने र संस्थाको policy अनुसार खोज तथा escalation गर्नुपर्छ।","OT Safety"]];const topics=[["1. Anatomy & Physiology (10%)","Anatomical terms, body organization, cells, tissues and body regions; overview of GIT, respiratory, excretory, genital, endocrine, special senses, nervous, lymphatic and skeletal systems. Physiology of muscular, nervous, cardiovascular, respiratory, digestive, excretory, endocrine and reproductive systems.","शरीरका anatomical terms, cell/tissue, अंग र प्रणालीको आधारभूत बनावट तथा मांसपेशी, स्नायु, मुटु–रक्तसञ्चार, श्वासप्रश्वास, पाचन, उत्सर्जन, endocrine र प्रजनन प्रणालीको कार्य पढ्नुहोस्।"],["2. Biochemistry (part of 15%)","Biochemistry and scope; electrolytes; carbohydrate digestion and absorption; blood glucose regulation; urea and creatinine formation; tests for sugar, urea, creatinine and protein in blood/urine; renal function tests; urine physical and chemical characteristics; blood pH regulation.","Electrolytes, carbohydrate digestion, glucose control, urea/creatinine, blood तथा urine test, renal function test, urine analysis र acid–base balance बुझ्नुहोस्।"],["3. Pharmacology (part of 15%)","Materia medica, drug standards and laws, dosage, minimum/maximum/toxic/lethal doses, idiosyncrasy, hypersensitivity, local/systemic action and routes. Common analgesics, antiseptics, disinfectants, antibiotics, tranquilizers, sulfonamides and local/general anaesthetics.","औषधिको मात्रा, route, local/systemic action, allergy/hypersensitivity, toxicity, analgesics, antiseptics, disinfectants, antibiotics र local/general anaesthetic को आधारभूत ज्ञान पढ्नुहोस्।"],["4. Microbiology (part of 15%)","Sterilization and disinfection; bacterial classification, morphology and reproduction; immunity; Staphylococcus, Streptococcus, diphtheria, Clostridium tetani/perfringens, anthrax, Mycobacterium tuberculosis/leprosy, E. coli, Salmonella, Shigella, Vibrio, Pseudomonas; Candida, Cryptococcus; hepatitis, HIV, herpes; nosocomial infection, universal precautions and waste disposal.","Sterilization, disinfection, bacteria/virus/fungi, immunity, सूचीमा भएका रोगजनक, hospital-acquired infection, universal precautions र biomedical waste management अध्ययन गर्नुहोस्।"],["5. OT Fundamentals & Teamwork (40%)","Modern surgery and OT roles; learning objectives and standardized procedures; healthcare team, sterile/unst erile team members, direct patient care, administrative and support staff; teamwork and communication.","OT को भूमिका, scrub/circulating team, sterile तथा non-sterile सदस्य, teamwork, communication र standardized procedure बुझ्नुहोस्।"],["6. Patient-centred & Pre-operative Nursing","Patient needs and response to illness; physician-patient relationship; acceptance of operation; special needs; preoperative assessment, planning, implementation and evaluation; patient identification, checklist and preparation.","बिरामीको आवश्यकता, डर/प्रतिक्रिया, विशेष आवश्यकता, preoperative history, assessment, planning, checklist, consent र patient identification पढ्नुहोस्।"],["7. OT Physical Facilities, Asepsis & CSSD","OT layout, exchange and peripheral support areas; contamination sources; surgical conscience; sterile technique principles; infection prevention; bioburden; sterilization parameters and monitoring; disinfection; CSSD.","OT layout, asepsis, sterile field, contamination, infection prevention, sterilization monitoring र Central Sterile Supply Department (CSSD) पढ्नुहोस्।"],["8. Scrub, Gowning, Gloving, Counts & Cleaning","Surgical hand scrub/hand antisepsis; sterile gown and gloves; scrub and circulating duties; sponge, sharp and instrument counts; setup; daily, weekly and monthly OT cleaning; waste segregation.","Surgical hand antisepsis, gown/glove लगाउने तरिका, sponge/sharp/instrument count, OT setup, सफाइ र waste segregation पढ्नुहोस्।"],["9. Safety, Equipment & Specimens","Time/motion and supply economy; disposable vs reusable equipment; instrument care; electrical and radiation hazards; medical gas, vacuum suction and scavenging; cautery and harmonic scalpel; specimen handling for histopathology and microbiology.","उपकरणको सुरक्षित प्रयोग, electrical/radiation hazard, gas pipeline, suction, scavenging, cautery, harmonic scalpel र specimen labelling/transport बुझ्नुहोस्।"],["10. Anaesthesia & Allied Topics","Pain, premedication, choice and stages of anaesthesia; general, local, regional, spinal and epidural techniques; neuromuscular blockers; balanced anaesthesia; anaesthetized patient care; neonatal/elderly considerations; equipment and occupational hazards; complications.","Anaesthesia का प्रकार, premedication, airway, anaesthesia equipment, muscle relaxants, बिरामीको निगरानी, विशेष उमेर समूह र complication पढ्नुहोस्।"],["11. Anaesthesia Drugs, CPR, Fluids & Blood","Anaesthetic drugs; narcotic/non-narcotic analgesics; steroids, bronchodilators, antihistamines, vasopressors, vasodilators, cardiomimetics and antiarrhythmics; CPR; venous access, cannulae, administration sets, crystalloids/colloids; blood groups, crossmatch, storage, incompatibility and transfusion reactions.","Anaesthesia तथा emergency औषधि, CPR, IV access, fluids, blood group/crossmatch, transfusion र transfusion reaction को आधारभूत ज्ञान पढ्नुहोस्।"],["12. Medico-legal, Accountability & Patient Safety","Medico-legal aspects, liability, accountability, patient and employee safety programmes, stress, clinical competence and professional conduct.","Consent, documentation, confidentiality, liability, accountability, patient safety र कर्मचारी सुरक्षा बुझ्नुहोस्।"],["13. Ambulatory, Monitoring, Positioning & Draping (35%)","Ambulatory surgery and recovery/discharge; patient reception and checklist; vital-function monitoring and complications; supine, prone, lateral, lithotomy and other operative positions; pressure/nerve injury risks; operative-site preparation, NG intubation, urinary catheterization and draping.","Day surgery, recovery, vital monitoring, operative positions, nerve/pressure injury, skin preparation, NG tube, urinary catheter र draping पढ्नुहोस्।"],["14. Wounds, Haemostasis & Closure","Wound healing and influencing factors; haemostasis methods; sutures, needles, suturing techniques, staples, tissue adhesives, repair/replacement materials and skin closure.","Wound healing का चरण, haemostasis, suture/needle प्रकार, suturing, staples र tissue adhesive बुझ्नुहोस्।"],["15. State-of-the-art & Diagnostic Procedures","Electrosurgery, laser surgery, endoscopy, microsurgery; radiology, ultrasonography, endoscopy, plethysmography and evoked potentials; laparoscopic surgery and instruments.","Electrosurgery, laser, endoscopy, microsurgery, imaging/diagnostic procedures र laparoscopy का उपकरण/सिद्धान्त पढ्नुहोस्।"],["16. Operative Procedures by Specialty","General surgery (neck, breast, abdominal, biliary, liver, spleen, pancreas, oesophagus, stomach, intestine, colorectal/anorectal, hernia, amputation); Gynaecology/obstetrics; Orthopaedics; Ophthalmology; ENT; plastic/reconstructive and burns; paediatric; cardiac and vascular; thoracic; urology; transplantation; oncology; neurosurgery; head and neck.","General surgery, Gynae/Obs, Orthopaedics, Eye, ENT, Plastic, Paediatric, Cardiac, Vascular, Thoracic, Urology, Transplant, Oncology, Neurosurgery र Head & Neck का common operation तथा OT तयारी पढ्नुहोस्।"],["17. Complications & Laparoscopy","Pulmonary and cardiovascular complications, shock, haemorrhage, DIC, wound infection/dehiscence, abdominal and renal complications, electrolyte imbalance; laparoscopic equipment and procedures.","Postoperative pulmonary/CVS complication, shock, bleeding, DIC, wound infection/dehiscence, renal/electrolyte समस्या र laparoscopic procedures अध्ययन गर्नुहोस्।"],["18. Practical Skills","Instrument washing and ultrasonic bath; identify instruments for surgeries; identify anaesthesia equipment; handle sophisticated anaesthetic/surgical equipment; OT waste disposal; position patients; handle sterile materials; sterilize laparoscopic/endoscopic instruments.","Instrument washing, ultrasonic bath, instrument identification, anaesthesia equipment, waste disposal, patient positioning, sterile material handling र laparoscopic/endoscopic instrument sterilization अभ्यास गर्नुहोस्।"]];const state={mode:"",items:[],index:0,answers:{}};
const h=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const panel=html=>root.innerHTML=html;
const bank=Q.map((q,i)=>{const shift=(i*7+3)%4;const options=q[2].map((_,j)=>q[2][(j+shift)%4]);return [...q.slice(0,2),options,(q[3]-shift+4)%4,...q.slice(4)];});
function menu(){panel('<div class="notice"><b>NHPC Diploma in Operation Theatre Technology</b><p>आधिकारिक २०२१ syllabus का सबै मुख्य शीर्षक र उपशीर्षकलाई अध्ययन नक्सामा राखिएको छ। हाल १०५ वटा मौलिक bilingual MCQ छन्। syllabus अनुसार थप प्रश्न र विस्तृत Notes क्रमशः थपिँदैछन्।</p></div><div class="topic-grid">'+topics.map(t=>'<article class="topic-card"><b>'+h(t[0])+'</b><small>'+h(t[1])+'</small><p>'+h(t[2])+'</p></article>').join('')+'</div><h3>MCQ अभ्यास</h3><div class="ha-actions"><button data-ott="practice">MCQ Practice (49)</button><button data-ott="mock">Mini Mock Test (56)</button></div><h3>अध्ययन कसरी गर्ने?</h3><ol><li>पहिले सम्बन्धित topic को Notes पढ्नुहोस्।</li><li>MCQ Practice मा उत्तर छानेर तुरुन्त व्याख्या हेर्नुहोस्।</li><li>Mock Test मा सबै प्रश्न हल गरेपछि मात्र नतिजा हेर्नुहोस्।</li><li>गल्ती भएका प्रश्नको English र नेपाली व्याख्या दोहोर्‍याउनुहोस्।</li></ol><p class="disclaimer">यो स्वतन्त्र शैक्षिक अभ्यास सामग्री हो, आधिकारिक प्रश्नपत्र होइन। clinical काममा आफ्नो scope, संस्थागत SOP र जिम्मेवार clinician को निर्देशन पालना गर्नुहोस्।</p>');}
function begin(mode){state.mode=mode;state.items=bank.slice(mode==="practice"?0:49,mode==="practice"?49:bank.length);state.index=0;state.answers={};render();}
function render(){const q=state.items[state.index],sel=state.answers[state.index],done=sel!==undefined;panel('<p class="muted">'+(state.mode==="practice"?"MCQ Practice":"Mini Mock Test")+' • प्रश्न '+(state.index+1)+' / '+state.items.length+' • '+h(q[6])+'</p><article class="ha-question"><h3>'+h(q[0])+'</h3><p class="np">'+h(q[1])+'</p><div class="ha-options">'+q[2].map((o,i)=>'<button class="'+(sel===i?"selected":"")+'" data-ott-option="'+i+'">'+String.fromCharCode(65+i)+'. '+h(o)+'</button>').join("")+'</div>'+(done?'<div class="ha-explain"><b>'+(sel===q[3]?"सही उत्तर!":"सही उत्तर: "+h(q[2][q[3]]))+'</b><p>'+h(q[4])+'</p><p class="np">'+h(q[5])+'</p></div>':"")+'</article><div class="ha-nav"><button data-ott-prev '+(state.index===0?"disabled":"")+'>← अघिल्लो</button><button data-ott-next>'+(state.index===state.items.length-1?"नतिजा हेर्नुहोस्":"अर्को →")+'</button></div><button data-ott="menu" class="smallbtn">मुख्य मेनु</button>');}
function finish(){let score=0;const rows=state.items.map((q,i)=>{const ok=state.answers[i]===q[3];if(ok)score++;return '<article class="ha-review"><b>'+(i+1)+'. '+h(q[0])+'</b><p class="'+(ok?"correct":"incorrect")+'">'+(ok?"सही उत्तर":"गलत/छुटेको उत्तर")+' • '+h(q[2][q[3]])+'</p><p>'+h(q[4])+'</p><p class="np">'+h(q[5])+'</p></article>';});if(window.DHPNProgress)window.DHPNProgress.recordMock("NHPC Diploma in Operation Theatre Technology",score,state.items.length);panel('<div class="ha-result"><h3>अभ्यास नतिजा</h3><div class="ha-score">'+score+' / '+state.items.length+'</div><b>'+Math.round(score/state.items.length*100)+'% सही</b><p>यो अभ्यास नतिजा हो, NHPC को आधिकारिक pass mark होइन।</p></div><h3>उत्तर समीक्षा</h3>'+rows.join("")+'<button data-ott="menu" class="smallbtn">मुख्य मेनुमा फर्कनुहोस्</button>');}
root.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.ott){if(b.dataset.ott==="menu")menu();else begin(b.dataset.ott);return;}if(b.dataset.ottOption!==undefined){state.answers[state.index]=Number(b.dataset.ottOption);render();if(state.mode==="practice"&&window.DHPNProgress){const q=state.items[state.index];window.DHPNProgress.recordMCQ("NHPC Diploma in Operation Theatre Technology",[q[0],q[1],q[2],q[3],q[4],q[5]],state.answers[state.index]);}return;}if(b.dataset.ottPrev!==undefined){state.index=Math.max(0,state.index-1);render();return;}if(b.dataset.ottNext!==undefined){if(state.index===state.items.length-1){if(state.items.some((_,i)=>state.answers[i]===undefined)){alert("सबै प्रश्नको उत्तर दिएपछि मात्र नतिजा हेर्नुहोस्।");return;}finish();}else{state.index++;render();}}});menu();})();